def crypto_decrypt(session, algorithm, key, data):
    """
    Decrypt (AES-GCM)

    Decrypt AES-GCM ciphertext. algorithm must include name, iv, and tag (16
    octets). additionalData must match encrypt if used. Requires execute
    access. Auth failure yields a generic decryption error.

    Args:
        algorithm (dict): AES-GCM parameters including required iv and tag.

        key (object): Key material, CryptoKey, or key reference.

        data (object): Ciphertext without tag (base64Binary or hexBinary).

    Returns:
        object: Plaintext octets.
    """

    request = session.Request()

    action = {
        "function": "crypto_decrypt",
        "algorithm": algorithm,
        "key": key,
        "data": data
    }

    request.add_action(action)

    response = request.perform()
    if response.get('status') == 'error':
        raise Exception(response.get('error'))

    return response['actions'][0]['result']

